#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    static int total;
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {
        total = total + f;
    }
};

int Cat::total = 0;

int main() {
    Cat a("小橘", 3);
    Cat b("狸花", 4);
    a.fish = 100;
    cout << "一共 " << Cat::total << " 条" << endl;
    cout << "小橘 " << a.fish << " 条" << endl;
    cout << "狸花 " << b.fish << " 条" << endl;
    return 0;
}
